function updateInventory(array $inventory, string $item, int $quantity): array {
    $newInventory = [];
    $itemExists = false;

    foreach ($inventory as $key => $value) {
        if ($key === $item) {
            $newInventory[$key] = $value + $quantity;
            $itemExists = true;
        } else {
            $newInventory[$key] = $value;
        }
    }

    if (!$itemExists) {
        $newInventory[$item] = $quantity;
