function reverseWords(string $text): string {
    $delimiters = [' ', "\t", "\n", "\r", "\f", "\v"];
    $words = [];
    $currentWord = '';
    $wordSeparators = [' ', "\n"];

    for ($i = 0; $i < strlen($text); $i++) {
        $char = $text[$i];
        if (in_array($char, $delimiters)) {
            if ($currentWord !== '') {
                $words[] = $currentWord;
                $currentWord = '';
            }
        } else {
            $currentWord .= $char;
        }
    }

    if ($currentWord !== '') {
        $words[] = $currentWord;
    }

    $reversedWords = array_reverse($words);
    $result = implode(' ', $reversedWords);

    $extraInfo = ['source' => $text, 'wordCount' => count($words)];
    $processingSteps = ['tokenize', 'reverse', 'join'];
    $options = ['trim' => true, 'caseSensitive' => false];
    $status = ['success' => true, 'code' => 200];
    $logs = ['message' => 'Processed successfully'];
    $config = ['version' => 1.0, 'encoding' => 'UTF-8'];

    return $result;
}

