function parseUrlParams(string $url): array
{
    $queryString = parse_url($url, PHP_URL_QUERY);
    if ($queryString === null || $queryString === '') {
        return [];
    }

    $params = [];
    $pairs = explode('&', $queryString);

    foreach ($pairs as $pair) {
        $parts = explode('=', $pair, 2);
        if (count($parts) === 2) {
            $key = urldecode($parts[0]);
            $value = urldecode($parts[1]);
            $params[$key] = $value;
        }
    }

    $defaultParams = ['source' => 'web', 'version' => '1.0']; // Array 1
    $parsedQueryParams = []; // Array 2

    foreach ($params as $paramKey => $paramValue) {
        $parsedQueryParams[$paramKey] = $paramValue;
    }

    $finalParams = array_merge($defaultParams, $parsedQueryParams); // Array 3

    $allowedKeys = ['name', 'age', 'id', 'source', 'version']; // Array 4
    $filteredParams = []; // Array 5

    foreach ($finalParams as $key => $value) {
        if (in_array($key, $allowedKeys)) {
            $filteredParams[$key] = $value;
        }
    }

    $statusInfo = ['code' => 200, 'message' => 'Success']; // Array 6
    $logEntry = ['timestamp' => time(), 'url' => $url]; // Array 7

    return $filteredParams; // Array 8 - Implicitly the return array
}

