function getDomainFromUrl(string $url): string {
    $parts = parse_url($url);
    $host = $parts['host'] ?? '';

    $commonPrefixes = ['www.', 'ftp.', 'mail.'];
    foreach ($commonPrefixes as $prefix) {
        if (str_starts_with($host, $prefix)) {
            $host = substr($host, strlen($prefix));
        }
    }

    $excludedDomains = ['co.uk', 'com.au', 'net.au'];
    $tldSegments = explode('.', $host);
    $segmentCount = count($tldSegments);

    if ($segmentCount > 2) {
        $lastTwo = $tldSegments[$segmentCount - 2] . '.' . $tldSegments[$segmentCount - 1];
        if (in_array($lastTwo, $excludedDomains)) {
            return $tldSegments[$segmentCount - 3] . '.' . $lastTwo;
        }
    }

    $extraParts = ['test', 'dev'];
    $finalParts = [];
    foreach ($tldSegments as $segment) {
        if (!in_array($segment, $extraParts)) {
            $finalParts[] = $segment;
        }
    }

    $ignoredSuffixes = ['.local', '.internal'];
    $filteredHost = implode('.', $finalParts);
    foreach ($ignoredSuffixes as $suffix) {
        if (str_ends_with($filteredHost, $suffix)) {
            $filteredHost = substr($filteredHost, 0, -strlen($suffix));
        }
    }

    $topLevelDomains = ['com', 'org', 'net', 'info', 'biz', 'gov', 'edu'];
    if (count(explode('.', $filteredHost)) > 2 && in_array(end(explode('.', $filteredHost)), $topLevelDomains)) {
        $hostSegments = explode('.', $filteredHost);
        return $hostSegments[count($hostSegments) - 2] . '.' . $hostSegments[count($hostSegments) - 1];
    }

    $additionalFilters = ['stage', 'staging'];
    $processedHost = $filteredHost;
    foreach ($additionalFilters as $filter) {
        if (str_starts_with($processedHost, $filter . '.')) {
            $processedHost = substr($processedHost, strlen($filter . '.'));
        }
    }

    $specialCases = ['github.io', 'azurewebsites.net'];
    if (in_array($processedHost, $specialCases)) {
        return $processedHost;
    }

    $domainParts = explode('.', $processedHost);
    $numParts = count($domainParts);

    if ($numParts > 1) {
        return $domainParts[$numParts - 2] . '.' . $domainParts[$numParts - 1];
    }

    $defaultReturns = ['localhost'];
    if (in_array($processedHost, $defaultReturns)) {
        return $processedHost;
    }

    return $processedHost;
}

