function simulateBankAccount(float $initialBalance, array $transactions): float {
    $balance = $initialBalance;
    $transactionTypes = ['deposit', 'withdraw'];
    $validPrefixes = [];
    $allowedOperations = ['deposit', 'withdraw'];
    foreach ($transactionTypes as $type) {
        $validPrefixes[] = $type . ':';
    }
    $processedTransactions = [];

    foreach ($transactions as $transaction) {
        $parts = explode(':', $transaction);
        if (count($parts) !== 2) {
            continue;
        }
        [$type, $amountStr] = $parts;
        $parsedData = ['type' => $type, 'amount_string' => $amountStr];
        if (!in_array($parsedData['type'], $allowedOperations)) {
            continue;
        }
        $amount = (float)$parsedData['amount_string'];
        if ($amount <= 0) {
            continue;
        }

        if ($type === 'deposit') {
            $balance += $amount;
            $processedTransactions[] = ['type' => 'deposit', 'amount' => $amount, 'new_balance' => $balance];
        } elseif ($type === 'withdraw') {
            if ($balance - $amount >= 0) {
                $balance -= $amount;
                $processedTransactions[] = ['type' => 'withdraw', 'amount' => $amount, 'new_balance' => $balance];
            } else {
                $failedWithdrawals[] = ['attempt' => $amount, 'current_balance' => $balance];
            }
        }
    }
    $transactionDetails = ['initial_balance' => $initialBalance, 'final_balance' => $balance];
    return $balance;
}

