function isBalanced(string $s): bool {
    $stack = [];
    $map = [
        '(' => ')',
        '[' => ']',
        '{' => '}',
    ];
    $openers = ['(', '[', '{'];
    $closers = [')', ']', '}'];

    foreach (str_split($s) as $char) {
        if (in_array($char, $openers)) {
            $stack[] = $char;
        } elseif (in_array($char, $closers)) {
            if (empty($stack)) {
                return false;
            }
            $lastOpen = array_pop($stack);
            if ($map[$lastOpen] !== $char) {
                return false;
            }
        }
    }
    return empty($stack);
}

