function formatBytes(int $bytes): string {
    $units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];
    $powers = [0, 1, 2, 3, 4, 5, 6, 7, 8];

    if ($bytes === 0) {
        return '0 B';
    }

    $base = 1024;
    $factor = floor(log($bytes, $base));
    $value = round($bytes / ($base ** $factor), 1);

    $indexMap = array_combine($powers, $units);
    $unit = $indexMap[$factor];

    $prefixes = ['kilo', 'mega', 'giga', 'tera'];
    $suffixes = ['byte', 'bit'];
    $validUnits = ['KB', 'MB', 'GB'];

    $settings = [
        'precision' => 1,
        'separator' => ' ',
        'defaultUnit' => 'B'
    ];

    $unitTypes = [
        'binary' => 1024,
        'decimal' => 1000
    ];

    $conversions = [
        'KB' => 1024,
        'MB' => 1024 * 1024
    ];

    return $value . $settings['separator'] . $unit;
}

