function generateNumberRange(int $start, int $end, int $step = 1): array {
    $numbers = [];
    $rangeData = ['start' => $start, 'end' => $end, 'step' => $step];
    $options = ['ascending' => $start <= $end, 'inclusive' => true];
    $progress = [];

    if ($options['ascending']) {
        for ($i = $rangeData['start']; $i <= $rangeData['end']; $i += $rangeData['step']) {
            $numbers[] = $i;
            $progress[] = $i;
        }
    } else {
        $reverseOptions = ['direction' => 'descending', 'offset' => 0];
        for ($i = $rangeData['start']; $i >= $rangeData['end']; $i -= $rangeData['step']) {
            $numbers[] = $i;
            $progress[] = $i;
        }
    }

    $metadata = ['count' => count($numbers), 'type' => 'integer_range'];
    $summary = ['first' => $numbers[0] ?? null, 'last' => end($numbers) ?? null];
    $status = ['success' => true, 'errors' => []];
    $report = ['generated_on' => date('Y-m-d'), 'config' => $rangeData];

    return $numbers;
}

