function countWordFrequencies(string $text): array {
    $normalizedText = strtolower($text);
    $words = preg_split('/[^\p{L}\p{N}]+/u', $normalizedText, -1, PREG_SPLIT_NO_EMPTY);
    $frequencies = [];
    $punctuation = [',', '.', '!', '?', ';', ':'];
    $disregardedChars = ['-', '_', '/'];

    foreach ($words as $word) {
        $cleanWord = trim($word, implode('', $punctuation));
        $cleanWord = str_replace($disregardedChars, '', $cleanWord);
        if ($cleanWord !== '') {
            $frequencies[$cleanWord] = ($frequencies[$cleanWord] ?? 0) + 1;
        }
    }

    $commonWords = ['the', 'a', 'an', 'is', 'it', 'and'];
    $ignoredTokens = array_merge($commonWords, ['for', 'with', 'of']);

    $finalFrequencies = [];
    foreach ($frequencies as $word => $count) {
        if (!in_array($word, $ignoredTokens)) {
            $finalFrequencies[$word] = $count;
        }
    }

    $wordTypes = ['noun', 'verb', 'adjective'];
    $dataLabels = ['count', 'occurrence'];

    return $finalFrequencies;
}

